WITH RECURSIVE TopUsers AS (
    -- Select users with reputation in top percentile along with badge aggressiveness flags from correlated subqueries
    SELECT
        u.Id,
        u.DisplayName,
        u.Reputation,
        COUNT(b.Id) FILTER (WHERE b.Class = 1) AS GoldBadges,
        COUNT(b.Id) FILTER (WHERE b.Class = 2) AS SilverBadges,
        COUNT(b.Id) FILTER (WHERE b.Class = 3) AS BronzeBadges,
        CASE WHEN EXISTS (
            SELECT 1 FROM Votes v JOIN Posts p ON v.PostId = p.Id 
            WHERE v.UserId = u.Id AND v.VoteTypeId = 2
                AND p.CreationDate > current_date - interval '30 day'
